import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Understanding Ceph One Performance Counter at a Time - Marcel Lauhoff, Clyso GmbH","description":"","frontmatter":{"title":"Understanding Ceph One Performance Counter at a Time - Marcel Lauhoff, Clyso GmbH","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Performance Monitoring","Distributed Storage","Performance Counters","Data Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Understanding_Ceph_One_Performance_Counter_at_a_Time_-_Marcel_Lauhoff_Clyso_GmbH.md","filePath":"posts/2025/Understanding_Ceph_One_Performance_Counter_at_a_Time_-_Marcel_Lauhoff_Clyso_GmbH.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Understanding_Ceph_One_Performance_Counter_at_a_Time_-_Marcel_Lauhoff_Clyso_GmbH.md"};function l(i,e,s,_,p,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要-理解ceph性能计数器" tabindex="-1">会议纪要：理解Ceph性能计数器 <a class="header-anchor" href="#会议纪要-理解ceph性能计数器" aria-label="Permalink to &quot;会议纪要：理解Ceph性能计数器&quot;">​</a></h3><p><strong>会议主题</strong>: 通过性能计数器逐步理解Ceph的工作原理</p><p><strong>主讲人</strong>: Marcel Lauhoff, Clyso GmbH</p><p><strong>会议内容概述</strong>:</p><p>Marcel Lauhoff分享了他通过性能计数器来理解Ceph工作原理的学习历程。他通过一系列实验，展示了如何利用性能计数器分析Ceph的操作和延迟，并开发了一种直观的理解方法。</p><p><strong>主要议题</strong>:</p><ol><li><p><strong>性能计数器的定义与类型</strong>:</p><ul><li>性能计数器是运行时捕获的服务度量，在Ceph中称为perf counters，在其他上下文中通常称为metrics。</li><li>类型包括：Gauge（表示可测量的值）、Counter（递增的值）、Histogram（带有桶的计数器）、Long Running Average（长期平均值）。</li></ul></li><li><p><strong>实验与分析</strong>:</p><ul><li>通过简单的S3 PUT操作，分析了操作类型和延迟，发现涉及多个操作，包括写入和设置扩展属性。</li><li>通过S3基准测试，分析了不同操作的延迟分布，发现读取操作的延迟分布有两个峰值。</li></ul></li><li><p><strong>延迟分析</strong>:</p><ul><li>使用OSD的性能计数器分析读取、写入和读写操作的延迟。</li><li>使用直方图分析延迟分布，发现不同大小的操作延迟差异较大。</li></ul></li><li><p><strong>工具与方法</strong>:</p><ul><li>使用Admin Socket和Perf Dump获取性能计数器。</li><li>使用Histogram分析深入了解操作的延迟分布。</li></ul></li></ol><p><strong>决定事项</strong>:</p><ul><li>探索如何将性能计数器与Prometheus、Grafana等监控工具集成。</li><li>开发一个类似“top”工具的网络连接监控工具。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>研究将Ceph的性能计数器导出到Prometheus等监控系统中。</li><li>深入研究BlueStore的性能计数器。</li><li>开发网络连接监控工具。</li></ul><p><strong>会议总结</strong>: Marcel通过性能计数器展示了如何逐步理解Ceph的工作原理，强调了性能计数器在开发和调试中的重要性，并提出了进一步的研究和工具开发计划。</p>',12)])])}const m=r(n,[["render",l]]);export{c as __pageData,m as default};
